import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Ce1WstT_.js";const n="/fundsroom_infotech/assets/architecture/challan-concurrency-flow.svg",p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/concurrency.md","filePath":"system-design/concurrency.md"}'),c={name:"system-design/concurrency.md"};function s(r,e,l,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<div class="page-header"><span class="category-badge">SYSTEM DESIGN</span><h1>Concurrency &amp; Data Flow</h1><p class="page-subtitle">Pessimistic locking and ACID transactions to guarantee inventory accuracy.</p><hr class="header-divider"></div><p>The Fundsroom Mini ERP + CRM relies heavily on real-time inventory adjustments and sales dispatching. A critical design constraint is ensuring that stock is never oversold when multiple sales executives attempt to draft and confirm challans simultaneously.</p><h2 id="the-concurrency-problem" tabindex="-1">The Concurrency Problem <a class="header-anchor" href="#the-concurrency-problem" aria-label="Permalink to &quot;The Concurrency Problem&quot;">​</a></h2><p>If <code>User A</code> and <code>User B</code> both attempt to sell the last 10 units of a product at the exact same millisecond:</p><ol><li>Both read <code>current_stock = 10</code>.</li><li>Both evaluate <code>10 &gt;= 10</code> (True).</li><li>Both subtract 10 and write <code>current_stock = 0</code>.</li><li>Result: 20 units were sold, but only 10 existed. <strong>(Negative Stock)</strong></li></ol><h2 id="pessimistic-locking-solution" tabindex="-1">Pessimistic Locking Solution <a class="header-anchor" href="#pessimistic-locking-solution" aria-label="Permalink to &quot;Pessimistic Locking Solution&quot;">​</a></h2><p>To prevent this, the monolithic backend employs <strong>Pessimistic Row-Level Locking</strong> using PostgreSQL&#39;s <code>SELECT ... FOR UPDATE</code> clause within ACID transactions.</p><h3 id="the-transaction-flow" tabindex="-1">The Transaction Flow <a class="header-anchor" href="#the-transaction-flow" aria-label="Permalink to &quot;The Transaction Flow&quot;">​</a></h3><div class="architecture-container"><img src="'+n+'" alt="Challan Concurrency Flow"></div><p class="screenshot-caption">Figure 8 — Challan Concurrency Flow (Optimistic Validation &amp; Pessimistic Locks)</p><h3 id="why-for-no-key-update" tabindex="-1">Why <code>FOR NO KEY UPDATE</code>? <a class="header-anchor" href="#why-for-no-key-update" aria-label="Permalink to &quot;Why `FOR NO KEY UPDATE`?&quot;">​</a></h3><p>We use <code>FOR NO KEY UPDATE</code> instead of <code>FOR UPDATE</code> because we are only modifying the <code>current_stock</code> column of the product, not its primary key. This allows concurrent <code>INSERT</code> operations into related tables (like <code>stock_movements</code> or <code>challan_items</code>) without blocking them unnecessarily, maximizing throughput while maintaining integrity.</p><h2 id="rollback-behavior" tabindex="-1">Rollback Behavior <a class="header-anchor" href="#rollback-behavior" aria-label="Permalink to &quot;Rollback Behavior&quot;">​</a></h2><p>Because the entire confirmation process occurs within a single PostgreSQL transaction block, any failure—whether a database constraint violation, a network error midway, or an application-level throw—will trigger an automatic <code>ROLLBACK</code>.</p><p>This guarantees that:</p><ul><li>Stock is never deducted if the stock movement log fails to write.</li><li>A challan is never marked as <code>CONFIRMED</code> if the stock deduction fails.</li><li>The system remains in a perfectly consistent state regardless of intermittent errors.</li></ul>',16)])])}const g=t(c,[["render",s]]);export{p as __pageData,g as default};
